// UNIVERSAL REFERENCE (T&&) & PERFECT FORWARDING

// T&& binds to lvalue (T deduced as T&) or rvalue (T deduced as T)
template <typename T>
void wrapper(T&& arg) {
    // std::forward preserves the argument's original value category (lvalue/rvalue)
    sink(std::forward<T>(arg));
}

// Example Context
void sink(int& x) {}     // Target for lvalues
void sink(int&& x) {}    // Target for rvalues

int val = 10;
wrapper(val);        // T is int&. Forwarded as lvalue.
wrapper(20);         // T is int. Forwarded as rvalue.

// Note: std::forward is implementationally a conditional static_cast<T&&>(arg)
// based on the deduction of T.
